+// discount-strategy.ts
+export interface DiscountStrategy {
+  apply(price: number, ctx: DiscountContext): number;
+}
+
+// discount-registry.ts
+export class DiscountRegistry {
+  private strategies = new Map<string, DiscountStrategy>();
+  register(key: string, s: DiscountStrategy) { this.strategies.set(key, s); }
+  resolve(key: string): DiscountStrategy {
+    return this.strategies.get(key) ?? this.strategies.get('default')!;
+  }
+}
+
+// discounts/flat-ten.ts
+export class FlatTenPercent implements DiscountStrategy {
+  apply(price: number) { return price * 0.9; }
+}
+
+// bootstrap.ts — the ONLY strategy ever registered
+registry.register('default', new FlatTenPercent());
